(window.CARDS = window.CARDS || {}).invention = [{"name":"Колесо","emoji":"🛞","meta":["около 5500 лет назад","Месопотамия","механика"],"description":"Одно из древнейших изобретений человечества впервые появилось в Месопотамии как деталь гончарного круга, а затем стало применяться в транспорте. Колесо лежит в основе почти всех механизмов с вращением — от телег до современных турбин.","fact":"Индейцы доколумбовой Америки знали принцип колеса — он встречается в детских игрушках — но не применяли его в транспорте.","wiki_en":"Wheel"},{"name":"Письменность","emoji":"📜","meta":["около 5000 лет назад","Шумер и Египет","передача информации"],"description":"Система знаков для фиксации речи возникла независимо в нескольких древних цивилизациях — клинопись в Шумере и иероглифы в Египте. Она позволила хранить законы, сделки и знания за пределами человеческой памяти.","fact":"Древнейшие известные тексты — это не литература, а хозяйственные записи и списки товаров.","wiki_en":"History of writing"},{"name":"Бумага","emoji":"📄","meta":["около 100 года н. э.","Китай","письмо и печать"],"description":"Материал для письма изобрели в Китае, где его делали из измельчённых волокон коры, тряпья и растений. Секрет производства долго оставался в тайне, прежде чем распространился по миру через Ближний Восток в Европу.","fact":"По легенде, технологию изготовления бумаги приписывают китайскому чиновнику Цай Луню.","wiki_en":"Papermaking"},{"name":"Порох","emoji":"💥","meta":["около IX века","Китай","военное дело"],"description":"Смесь селитры, серы и угля впервые получили китайские алхимики, искавшие эликсир бессмертия. Позже порох стали применять для фейерверков, а затем и в огнестрельном оружии, изменившем ход войн.","fact":"В Европе порох начали широко применять заметно позже, чем в Китае, — с появлением первых пушек в XIV веке.","wiki_en":"Gunpowder"},{"name":"Компас","emoji":"🧭","meta":["около XI века","Китай","навигация"],"description":"Прибор, использующий свойство намагниченной стрелки указывать на магнитные полюса Земли, впервые описан в Китае. Он стал важнейшим инструментом мореплавателей, позволившим совершать дальние путешествия без ориентиров на суше.","fact":"Первые компасы в Китае применяли не для навигации в море, а для гадания и геомантии фэншуй.","wiki_en":"Compass"},{"name":"Печатный станок","emoji":"🖨️","meta":["около 1440 года","Иоганн Гутенберг","книгопечатание"],"description":"Устройство с подвижными литерами для быстрого тиражирования текста создал немецкий мастер Иоганн Гутенберг. Оно сделало книги доступнее и заметно ускорило распространение знаний по Европе.","fact":"Первой крупной книгой, напечатанной Гутенбергом, стала Библия, известная как «Библия Гутенберга».","wiki_en":"Printing press"},{"name":"Очки","emoji":"👓","meta":["конец XIII века","Италия","коррекция зрения"],"description":"Линзы для улучшения зрения появились в средневековой Италии, предположительно в Пизе или Венеции, где ремесленники научились шлифовать стекло нужной формы. Со временем очки стали доступным способом справляться с возрастной дальнозоркостью.","fact":"Первые очки не имели дужек для ушей — их просто держали в руке или зажимали на переносице.","wiki_en":"Glasses"},{"name":"Телескоп","emoji":"🔭","meta":["1608 год","Нидерланды","астрономия"],"description":"Оптический прибор для наблюдения удалённых объектов известен с 1608 года, когда нидерландский мастер Ханс Липперсхей подал на него патентную заявку. Позже Галилео Галилей усовершенствовал конструкцию и направил её на небо, открыв спутники Юпитера.","fact":"Галилей не изобрёл телескоп, но первым систематически применил его для астрономических наблюдений.","wiki_en":"Telescope"},{"name":"Микроскоп","emoji":"🔬","meta":["конец XVI века","Нидерланды","оптика"],"description":"Прибор для увеличения мелких объектов создали нидерландские мастера очков, среди которых называют семью Янссен. Позже Антони ван Левенгук с его помощью впервые разглядел бактерии и другие микроорганизмы.","fact":"Левенгук достигал огромного увеличения с помощью одной-единственной крошечной линзы собственной шлифовки.","wiki_en":"Microscope"},{"name":"Механические часы","emoji":"🕰️","meta":["около XIII века","Западная Европа","измерение времени"],"description":"Устройства с зубчатыми колёсами и спуском для равномерного отсчёта времени появились в средневековых европейских монастырях. Они заменили водяные и песочные часы и позволили точнее организовывать городскую жизнь.","fact":"Первые механические часы устанавливали на башнях соборов и не имели циферблата — они только отбивали часы звоном.","wiki_en":"History of timekeeping devices"},{"name":"Паровая машина","emoji":"⚙️","meta":["1769 год","Джеймс Уатт","промышленность"],"description":"Двигатель, преобразующий энергию пара в механическую работу, усовершенствовал шотландский инженер Джеймс Уатт, добавив отдельный конденсатор к более ранним конструкциям. Это изобретение стало движущей силой промышленной революции.","fact":"До Уатта паровые машины уже применял Томас Ньюкомен, но они были крайне неэффективны по расходу топлива.","wiki_en":"Steam engine"},{"name":"Паровоз","emoji":"🚂","meta":["1804 год","Ричард Тревитик","железнодорожный транспорт"],"description":"Первый действующий локомотив на паровой тяге построил британский изобретатель Ричард Тревитик. Позже Джордж Стефенсон усовершенствовал конструкцию и построил первые железные дороги общего пользования.","fact":"Паровоз Тревитика впервые показали в деле на металлургическом заводе — по заводским рельсам он вёз груз железа и людей.","wiki_en":"Steam locomotive"},{"name":"Пароход","emoji":"🚢","meta":["конец XVIII века","несколько изобретателей","водный транспорт"],"description":"Суда с паровым двигателем испытывали в разных странах, но коммерчески успешным первым стал пароход американца Роберта Фултона, начавший регулярные рейсы по реке Гудзон. Пароходы вытеснили парусный флот на реках и в океане.","fact":"Пароход Фултона современники прозвали «безумством Фултона», не веря в успех предприятия.","wiki_en":"Steamboat"},{"name":"Лампа накаливания","emoji":"💡","meta":["XIX век","среди пионеров — Эдисон и Лодыгин","освещение"],"description":"Над созданием практичной электрической лампы работали сразу несколько изобретателей в разных странах, включая Александра Лодыгина и Джозефа Суона. Томас Эдисон довёл конструкцию до коммерческого успеха, подобрав долговечную нить накаливания.","fact":"Эдисон перепробовал тысячи материалов для нити накала, прежде чем остановился на обугленном бамбуковом волокне.","wiki_en":"Incandescent light bulb"},{"name":"Электрическая батарея","emoji":"🔋","meta":["1800 год","Алессандро Вольта","источники тока"],"description":"Первый источник постоянного электрического тока — вольтов столб из чередующихся дисков цинка, меди и ткани, пропитанной солёным раствором, — создал итальянский физик Алессандро Вольта. Это изобретение открыло эпоху практического использования электричества.","fact":"В честь Вольты названа единица измерения электрического напряжения — вольт.","wiki_en":"Electric battery"},{"name":"Телеграф","emoji":"📡","meta":["1830-е годы","Сэмюэл Морзе и другие","связь"],"description":"Электрический телеграф для передачи сообщений по проводам разработали независимо несколько изобретателей, но наибольшую известность получила система Сэмюэла Морзе с одноимённой азбукой точек и тире. Телеграф впервые позволил передавать новости почти мгновенно на огромные расстояния.","fact":"Азбуку Морзе создавал не сам Морзе в одиночку — его помощник Альфред Вейл внёс большой вклад в её разработку.","wiki_en":"Electrical telegraph"},{"name":"Телефон","emoji":"☎️","meta":["1876 год","патент получил Александр Белл","связь"],"description":"Устройство для передачи голоса по проводам запатентовал Александр Грэм Белл, хотя над похожими конструкциями одновременно работали и другие изобретатели, включая Элишу Грея. Телефон быстро изменил деловую и повседневную жизнь, сделав возможным мгновенное общение на расстоянии.","fact":"Заявку Белла и бумаги его конкурента Элиши Грея подали в патентное ведомство в один и тот же день — 14 февраля 1876 года.","wiki_en":"Telephone"},{"name":"Радио","emoji":"📻","meta":["конец XIX века","среди пионеров — Попов и Маркони","связь"],"description":"Передачу сигналов без проводов с помощью электромагнитных волн демонстрировали независимо друг от друга несколько изобретателей, включая Александра Попова и Гульельмо Маркони. Маркони первым довёл технологию до коммерческого применения и наладил трансатлантическую связь.","fact":"В России днём радио традиционно считают 7 мая — дату публичной демонстрации приёмника Поповым.","wiki_en":"Radio"},{"name":"Фотография","emoji":"📷","meta":["1820-е годы","Жозеф Ньепс","изображение"],"description":"Первый устойчивый снимок с натуры получил француз Жозеф Нисефор Ньепс с помощью камеры-обскуры и светочувствительного вещества. Позже Луи Дагер усовершенствовал процесс, создав более чёткий и быстрый способ съёмки — дагеротипию.","fact":"Первому в истории сохранившемуся фотоснимку Ньепса требовалась выдержка в несколько часов.","wiki_en":"Photography"},{"name":"Кинематограф","emoji":"🎬","meta":["1895 год","братья Люмьер","движущееся изображение"],"description":"Публичный платный показ фильмов с помощью проекционного аппарата организовали французские братья Огюст и Луи Люмьер в парижском кафе. До этого схожие эксперименты вели и другие изобретатели, включая Томаса Эдисона с его кинетоскопом.","fact":"Один из первых фильмов Люмьеров — «Прибытие поезда» — якобы заставлял зрителей вскакивать с мест от испуга.","wiki_en":"Cinematograph"},{"name":"Телевизор","emoji":"📺","meta":["1920–1930-е годы","среди пионеров — Зворыкин и Бэрд","вещание"],"description":"Устройство для передачи движущегося изображения на расстояние создавалось усилиями нескольких изобретателей: шотландец Джон Лоджи Бэрд показал механическую систему, а Владимир Зворыкин и Фило Фарнсуорт развили электронную технологию, ставшую основой современного ТВ.","fact":"Первые телевизионные передачи Бэрда использовали вращающийся диск, а не электронную развёртку.","wiki_en":"History of television"},{"name":"Фонограф","emoji":"🎙️","meta":["1877 год","Томас Эдисон","звукозапись"],"description":"Первый прибор для записи и воспроизведения звука на фольге создал американский изобретатель Томас Эдисон. Фонограф положил начало всей индустрии звукозаписи, хотя позже был вытеснен более удобным граммофоном.","fact":"Первой фразой, записанной Эдисоном на фонограф, была детская песенка про овечку Мэри.","wiki_en":"Phonograph"},{"name":"Двигатель внутреннего сгорания","emoji":"🔧","meta":["XIX век","несколько изобретателей","механика"],"description":"Двигатель, в котором топливо сжигается прямо в рабочем цилиндре, разрабатывали разные инженеры, а практичный четырёхтактный двигатель создал немец Николаус Отто. Позже Карл Бенц и Готлиб Даймлер применили такие двигатели в первых автомобилях.","fact":"Первый образец такого двигателя работал на смеси угольного газа, а не бензина.","wiki_en":"Internal combustion engine"},{"name":"Автомобиль","emoji":"🚗","meta":["1886 год","Карл Бенц","транспорт"],"description":"Первый практичный автомобиль с бензиновым двигателем запатентовал немецкий инженер Карл Бенц. Его жена Берта Бенц совершила на этой машине первую в истории дальнюю автомобильную поездку, доказав пригодность изобретения.","fact":"Топливо для своей поездки Берта Бенц купила в аптеке — других мест, где его продавали, тогда попросту не было.","wiki_en":"Car"},{"name":"Велосипед","emoji":"🚲","meta":["начало XIX века","Карл фон Дрез","транспорт"],"description":"Прообраз велосипеда — деревянную беговую машину без педалей — придумал немецкий барон Карл фон Дрез. Педали и цепной привод добавили позже другие изобретатели, превратив «дрезину» в привычный двухколёсный транспорт.","fact":"Первые велосипеды не имели педалей — ездок отталкивался ногами от земли, как на самокате.","wiki_en":"Bicycle"},{"name":"Мотоцикл","emoji":"🏍️","meta":["1885 год","Готлиб Даймлер","транспорт"],"description":"Первое двухколёсное транспортное средство с двигателем внутреннего сгорания построили немцы Готлиб Даймлер и Вильгельм Майбах. Деревянная рама этой машины имела дополнительные боковые колёсики для устойчивости.","fact":"Первый мотоцикл Даймлера называли «верховой повозкой» — само слово «мотоцикл» появилось позже.","wiki_en":"Motorcycle"},{"name":"Самолёт","emoji":"✈️","meta":["1903 год","среди пионеров — братья Райт","авиация"],"description":"Первый управляемый полёт аппарата тяжелее воздуха с собственным двигателем совершили американцы братья Уилбур и Орвилл Райт в Кити-Хок. Их достижению предшествовали десятилетия экспериментов планеристов и инженеров по всему миру.","fact":"Первый полёт братьев Райт длился всего около двенадцати секунд и преодолел меньше сорока метров.","wiki_en":"Airplane"},{"name":"Вертолёт","emoji":"🚁","meta":["1939 год","Игорь Сикорский","авиация"],"description":"Первый практичный вертолёт с одним несущим и хвостовым винтом построил американский инженер российского происхождения Игорь Сикорский. До него идею винтокрылой машины изучали многие изобретатели, включая Леонардо да Винчи в своих набросках.","fact":"Сикорский эмигрировал из России после революции и продолжил конструкторскую карьеру уже в США.","wiki_en":"Helicopter"},{"name":"Воздушный шар","emoji":"🎈","meta":["1783 год","братья Монгольфье","воздухоплавание"],"description":"Первый полёт человека на воздушном шаре с горячим воздухом организовали французские братья Жозеф и Этьен Монгольфье. Их первый пассажирский полёт над Парижем стал сенсацией и началом эпохи воздухоплавания.","fact":"Перед полётом людей братья Монгольфье отправили в небо первых «пассажиров» — овцу, утку и петуха.","wiki_en":"Hot air balloon"},{"name":"Дирижабль","emoji":"🛸","meta":["1900 год","граф Фердинанд фон Цеппелин","воздухоплавание"],"description":"Управляемый летательный аппарат с жёстким каркасом создал немецкий конструктор граф Фердинанд фон Цеппелин, чьё имя стало нарицательным для таких машин. Дирижабли недолго использовались для пассажирских перелётов, пока их не вытеснили самолёты.","fact":"Катастрофа дирижабля «Гинденбург» в 1937 году во многом положила конец эпохе пассажирских дирижаблей.","wiki_en":"Airship"},{"name":"Парашют","emoji":"🪂","meta":["конец XVIII века","Луи-Себастьен Ленорман","безопасность полётов"],"description":"Первый удачный прыжок с парашютом собственной конструкции совершил француз Луи-Себастьен Ленорман, спрыгнув с башни обсерватории в Монпелье. Позже конструкцию усовершенствовали, добавив ранец и купол из более прочной ткани.","fact":"Само слово «парашют» придумал Ленорман, соединив греческое «пара» и французское «шют» — падение.","wiki_en":"Parachute"},{"name":"Ракета","emoji":"🚀","meta":["XIII век","Китай","военное дело и космонавтика"],"description":"Простейшие пороховые ракеты для фейерверков и войны появились в средневековом Китае. В XX веке идею развили пионеры ракетостроения, включая Константина Циолковского и Роберта Годдарда, что привело к созданию ракет для полётов в космос.","fact":"Первые боевые ракеты в Китае применяли ещё в XIII веке против монгольских войск.","wiki_en":"Rocket"},{"name":"Искусственный спутник Земли","emoji":"🛰️","meta":["1957 год","СССР","космонавтика"],"description":"Первый искусственный спутник Земли — простой металлический шар с антеннами «Спутник-1» — запустил Советский Союз. Его сигнал, который могли принять радиолюбители по всему миру, открыл космическую эру и запустил гонку космических держав.","fact":"«Спутник-1» передавал в эфир простой сигнал «бип-бип», который слышали радиостанции по всей планете.","wiki_en":"Sputnik 1"},{"name":"Подводная лодка","emoji":"🛥️","meta":["начало XVII века","Корнелис Дреббель","морской и военный флот"],"description":"Первый действующий подводный аппарат, способный погружаться и двигаться под водой, построил голландский изобретатель Корнелис Дреббель для английского двора. Позже подводные лодки стали важнейшим видом военного флота, особенно в XX веке.","fact":"Первая подводная лодка Дреббеля приводилась в движение обычными вёслами, выведенными через кожаные уплотнения.","wiki_en":"Submarine"},{"name":"Динамит","emoji":"🧨","meta":["1867 год","Альфред Нобель","взрывчатые вещества"],"description":"Безопасную в обращении взрывчатку на основе нитроглицерина, пропитанного пористым веществом, изобрёл шведский химик Альфред Нобель. Прибыль от производства динамита впоследствии легла в основу знаменитой Нобелевской премии.","fact":"Нобель учредил премию своего имени отчасти потому, что не хотел остаться в истории лишь как «торговец смертью».","wiki_en":"Dynamite"},{"name":"Атомная бомба","emoji":"☢️","meta":["1945 год","Манхэттенский проект, США","военное дело"],"description":"Первое ядерное оружие создала группа учёных и инженеров в рамках Манхэттенского проекта под руководством физика Роберта Оппенгеймера. Его первое боевое применение в Японии в 1945 году навсегда изменило представления о войне и международной безопасности.","fact":"Первое испытание атомной бомбы получило кодовое название «Тринити» и прошло в пустыне Нью-Мексико.","wiki_en":"Nuclear weapon"},{"name":"Атомная электростанция","emoji":"⚛️","meta":["1954 год","СССР","энергетика"],"description":"Первую в мире атомную электростанцию, подключённую к энергосети, построили в советском городе Обнинске. Она доказала возможность мирного использования ядерной энергии для выработки электричества.","fact":"Обнинская АЭС проработала почти полвека и была остановлена лишь в 2002 году.","wiki_en":"Nuclear power plant"},{"name":"Автомат Калашникова","emoji":"🔫","meta":["1947 год","Михаил Калашников","стрелковое оружие"],"description":"Автоматический карабин под патрон промежуточной мощности разработал советский конструктор Михаил Калашников. Благодаря простоте и надёжности АК стал одним из самых распространённых видов стрелкового оружия в мире.","fact":"Цифра 47 в названии АК-47 указывает на год, которым датируется сам образец, — 1947-й.","wiki_en":"AK-47"},{"name":"Радар","emoji":"📡","meta":["1930-е годы","несколько стран независимо","военное дело"],"description":"Технологию обнаружения объектов с помощью отражённых радиоволн разрабатывали независимо в нескольких странах накануне Второй мировой войны, включая Великобританию и Германию. Радар сыграл решающую роль в обороне Великобритании во время «Битвы за Британию».","fact":"Слово «радар» изначально было английской аббревиатурой словосочетания «обнаружение и определение дальности по радио».","wiki_en":"Radar"},{"name":"Лазер","emoji":"🔴","meta":["1960 год","Теодор Мейман","оптика"],"description":"Первый действующий лазер на основе рубинового кристалла построил американский физик Теодор Мейман. Изобретение опиралось на теоретические работы многих учёных и быстро нашло применение в медицине, связи и промышленности.","fact":"Слово «лазер» — это аббревиатура английского выражения, означающего усиление света вынужденным излучением.","wiki_en":"Laser"},{"name":"Транзистор","emoji":"⚡","meta":["1947 год","Бардин, Браттейн и Шокли","электроника"],"description":"Полупроводниковый прибор, заменивший громоздкие электронные лампы, создали в американской лаборатории Bell Labs физики Джон Бардин, Уолтер Браттейн и Уильям Шокли. Транзистор стал основой всей современной электроники — от радиоприёмников до компьютеров.","fact":"За изобретение транзистора все трое его создателей получили Нобелевскую премию по физике.","wiki_en":"Transistor"},{"name":"Микропроцессор","emoji":"🧮","meta":["1971 год","компания Intel","вычислительная техника"],"description":"Первый серийный микропроцессор Intel 4004, разместивший всю логику процессора на одном кристалле, выпустила американская компания Intel. Это изобретение сделало возможным появление компактных персональных компьютеров.","fact":"Первый микропроцессор Intel создавался как чип для японского калькулятора, а не для компьютера.","wiki_en":"Microprocessor"},{"name":"Компьютер","emoji":"🖥️","meta":["середина XX века","несколько изобретателей","вычислительная техника"],"description":"Электронные вычислительные машины появились в 1940-х годах усилиями разных команд инженеров в Великобритании, США и Германии — среди ранних примеров ENIAC и «Колосс». Компьютеры постепенно превратились из огромных ламповых машин в устройства, доступные каждому.","fact":"ENIAC, одна из первых электронных вычислительных машин, весил около 27 тонн и занимал целую комнату.","wiki_en":"Computer"},{"name":"Персональный компьютер","emoji":"💻","meta":["1970-е годы","несколько компаний","вычислительная техника"],"description":"Компактные и доступные компьютеры для дома и офиса начали выпускать в 1970-х годах несколько компаний, включая Apple с моделью Apple II и IBM с IBM PC. Персональный компьютер сделал вычислительную технику массовым явлением.","fact":"Ранние персональные компьютеры продавались в виде наборов для самостоятельной сборки энтузиастами.","wiki_en":"Personal computer"},{"name":"Компьютерная мышь","emoji":"🖱️","meta":["1964 год","Дуглас Энгельбарт","устройства ввода"],"description":"Первый прототип манипулятора для управления курсором на экране создал американский инженер Дуглас Энгельбарт. Своё название устройство получило из-за провода, напоминавшего мышиный хвост.","fact":"Первая мышь Энгельбарта была деревянной и имела всего одну кнопку.","wiki_en":"Computer mouse"},{"name":"Интернет","emoji":"🌐","meta":["1960–1970-е годы","США, проект ARPANET","связь"],"description":"Сеть с коммутацией пакетов, объединившую компьютеры разных организаций, начали строить американские учёные в рамках военного и научного проекта ARPANET. Со временем эта технология переросла в глобальную сеть, связавшую весь мир.","fact":"Первое сообщение, отправленное по сети-предшественнице интернета, оборвалось после первых двух букв из-за сбоя.","wiki_en":"Internet"},{"name":"Всемирная паутина","emoji":"🕸️","meta":["1989 год","Тим Бернерс-Ли","связь"],"description":"Систему гипертекстовых страниц, связанных ссылками и доступных через браузер, придумал британский учёный Тим Бернерс-Ли, работая в научном центре ЦЕРН. Его изобретение превратило интернет из технической сети в удобное пространство для всех.","fact":"В 1993 году ЦЕРН отказался от прав на технологию веба и сделал её общественным достоянием — бесплатной для всех.","wiki_en":"World Wide Web"},{"name":"Электронная почта","emoji":"📧","meta":["1971 год","Рэй Томлинсон","связь"],"description":"Систему пересылки сообщений между разными компьютерами сети разработал американский программист Рэй Томлинсон. Он же предложил использовать символ «@» для разделения имени пользователя и названия компьютера-адресата.","fact":"Сам Томлинсон не помнил точного текста своего первого тестового письма — по его словам, это было что-то незначительное.","wiki_en":"Email"},{"name":"Мобильный телефон","emoji":"📱","meta":["1973 год","Мартин Купер","связь"],"description":"Первый звонок с портативного беспроводного телефона сделал инженер компании Motorola Мартин Купер, позвонив конкурентам из исследовательской лаборатории соперника прямо на улице. До коммерческого выпуска подобных устройств прошло ещё около десяти лет.","fact":"Первый мобильный телефон весил около килограмма, а время работы от батареи составляло лишь полчаса.","wiki_en":"Mobile phone"},{"name":"Смартфон","emoji":"📲","meta":["1992–1994 годы","IBM Simon","связь и вычисления"],"description":"Первым устройством, совместившим телефон с функциями компьютера и сенсорным экраном, считается IBM Simon. Массовым это направление стало гораздо позже, после выхода iPhone компании Apple, задавшего современный облик смартфонов.","fact":"IBM Simon умел отправлять факсы и электронную почту ещё в начале 1990-х годов.","wiki_en":"Smartphone"},{"name":"GPS","emoji":"🛰️","meta":["1970-е–1990-е годы","Министерство обороны США","навигация"],"description":"Систему глобального позиционирования по сигналам спутников разработали военные и инженеры США для нужд армии, а позже открыли для гражданского использования. Сегодня она лежит в основе навигации в автомобилях, телефонах и авиации.","fact":"Полноценную группировку из более чем двух десятков спутников GPS завершили только к середине 1990-х годов.","wiki_en":"Global Positioning System"},{"name":"Wi-Fi","emoji":"📶","meta":["1997 год","стандарт разработан коллективно","беспроводная связь"],"description":"Стандарт беспроводной передачи данных между устройствами разработала группа инженеров, работавших над спецификацией IEEE 802.11. Название Wi-Fi позже придумали маркетологи для упрощённого обозначения этой технологии.","fact":"Само слово «Wi-Fi» не является аббревиатурой, хотя его часто ошибочно расшифровывают как «wireless fidelity».","wiki_en":"Wi-Fi"},{"name":"Bluetooth","emoji":"🔵","meta":["1994 год","компания Ericsson","беспроводная связь"],"description":"Технологию беспроводной связи на коротких расстояниях разработали инженеры шведской компании Ericsson. Название и логотип технологии отсылают к скандинавскому королю Харальду Синезубому, объединившему датские земли.","fact":"Логотип Bluetooth составлен из двух рун, обозначающих инициалы короля Харальда Синезубого.","wiki_en":"Bluetooth"},{"name":"USB-флеш-накопитель","emoji":"💾","meta":["конец 1990-х годов","несколько компаний","хранение данных"],"description":"Компактные накопители на основе флеш-памяти с интерфейсом USB почти одновременно предложили несколько компаний, включая израильскую M-Systems. Устройство быстро вытеснило дискеты как самый удобный способ переносить файлы между компьютерами.","fact":"Первые USB-флешки вмещали всего несколько десятков мегабайт — на современный фильм в высоком качестве их бы не хватило.","wiki_en":"USB flash drive"},{"name":"Компакт-диск","emoji":"💿","meta":["1982 год","Sony и Philips","хранение данных и звук"],"description":"Оптический диск для цифровой записи звука совместно разработали компании Sony и Philips. Компакт-диск на десятилетия стал главным носителем музыки, вытеснив виниловые пластинки и кассеты.","fact":"Стандартная вместимость первых компакт-дисков составляла 74 минуты — этого, по легенде, требовала любимая симфония одного из инженеров.","wiki_en":"Compact disc"},{"name":"Цифровой фотоаппарат","emoji":"📷","meta":["1975 год","Стивен Сассон, Kodak","фотография"],"description":"Первый работающий прототип цифровой камеры собрал инженер компании Kodak Стивен Сассон. Устройство записывало чёрно-белое изображение на кассету и было размером с тостер, но заложило принцип всей современной цифровой фотографии.","fact":"Первому цифровому снимку Сассона требовалось около 23 секунд, чтобы записаться на плёнку кассеты.","wiki_en":"Digital camera"},{"name":"3D-принтер","emoji":"🖨️","meta":["1980-е годы","Чак Халл","производство"],"description":"Технологию послойного создания трёхмерных объектов из жидкого полимера, отвердевающего под лазером, запатентовал американский инженер Чак Халл. Он же ввёл в обиход термин «стереолитография», ставший одной из первых форм 3D-печати.","fact":"Компания, основанная Чаком Халлом после изобретения, — 3D Systems — до сих пор остаётся крупным игроком на рынке 3D-печати.","wiki_en":"3D printing"},{"name":"Беспилотник","emoji":"🛩️","meta":["XX век","военные разработки разных стран","авиация"],"description":"Летательные аппараты без пилота на борту развивались на протяжении всего XX века военными инженерами разных стран, от радиоуправляемых мишеней до современных разведывательных дронов. Сегодня беспилотники применяют в армии, съёмке и доставке грузов.","fact":"Одни из первых беспилотных аппаратов использовались как летающие мишени для тренировки зенитчиков.","wiki_en":"Unmanned aerial vehicle"},{"name":"Электромобиль","emoji":"🔌","meta":["XIX век","несколько изобретателей","транспорт"],"description":"Первые экипажи с электрическим двигателем появились ещё в XIX веке благодаря нескольким независимым изобретателям в Европе и США, задолго до бензиновых автомобилей. Из-за ограниченного запаса хода электромобили надолго уступили место машинам с двигателем внутреннего сгорания.","fact":"В начале XX века электромобили были очень популярны у женщин-водителей — их не нужно было заводить тяжёлой рукояткой.","wiki_en":"Electric vehicle"},{"name":"Солнечная батарея","emoji":"☀️","meta":["1954 год","лаборатория Bell Labs","энергетика"],"description":"Первый практичный кремниевый солнечный элемент, способный эффективно преобразовывать солнечный свет в электричество, создали инженеры американской компании Bell Labs. Это изобретение открыло путь к использованию солнечной энергии — от спутников до крыш жилых домов.","fact":"Одними из первых потребителей солнечных батарей стали космические спутники, где другие источники энергии почти невозможны.","wiki_en":"Solar cell"},{"name":"Ветрогенератор","emoji":"💨","meta":["конец XIX века","Джеймс Блит","энергетика"],"description":"Одну из первых ветряных установок для выработки электричества построил шотландский инженер Джеймс Блит, чтобы осветить свой дом. Современные ветрогенераторы выросли из этой идеи в огромные промышленные турбины, вырабатывающие электричество для целых регионов.","fact":"Соседи Блита поначалу отказывались от предложенного бесплатного электричества, считая его порождением дьявола.","wiki_en":"Wind turbine"},{"name":"Светодиод","emoji":"💡","meta":["1962 год","Ник Холоньяк","освещение и электроника"],"description":"Первый светодиод, светящийся в видимом красном спектре, создал американский инженер Ник Холоньяк, работавший в компании General Electric. Позже разработка светодиодов других цветов, включая синий, сделала возможными энергоэффективные лампы и экраны.","fact":"За изобретение синего светодиода, завершившего палитру цветов, в 2014 году присудили Нобелевскую премию по физике.","wiki_en":"Light-emitting diode"},{"name":"Холодильник","emoji":"🧊","meta":["XIX век","несколько изобретателей","бытовая техника"],"description":"Устройства для искусственного охлаждения продуктов разрабатывали разные инженеры на протяжении XIX века, а массовым бытовым прибором холодильник стал в начале XX века благодаря компаниям вроде General Electric. Он избавил людей от необходимости покупать лёд для хранения еды.","fact":"Первые бытовые холодильники были настолько дороги, что стоили как небольшой автомобиль.","wiki_en":"Refrigerator"},{"name":"Стиральная машина","emoji":"🧺","meta":["XIX–XX века","несколько изобретателей","бытовая техника"],"description":"Механические устройства для стирки белья постепенно совершенствовали инженеры на протяжении XIX века, а электрическую стиральную машину одним из первых выпустил американец Алва Фишер в начале XX века. Изобретение заметно облегчило домашний труд, особенно женский.","fact":"Ранние электрические стиральные машины не имели защитных механизмов и нередко травмировали руки хозяек отжимными валиками.","wiki_en":"Washing machine"},{"name":"Микроволновая печь","emoji":"📦","meta":["1945 год","Перси Спенсер","бытовая техника"],"description":"Свойство микроволн нагревать пищу случайно обнаружил американский инженер Перси Спенсер, заметивший, что шоколадка в его кармане растаяла рядом с работающим магнетроном. Так родилась идея бытовой печи, готовящей еду за считаные минуты.","fact":"Первая коммерческая микроволновая печь была размером с холодильник и весила больше 300 килограммов.","wiki_en":"Microwave oven"},{"name":"Пылесос","emoji":"🧹","meta":["начало XX века","Хьюберт Сесил Бут","бытовая техника"],"description":"Первый эффективный пылесос на основе всасывания воздуха, а не выдувания пыли, построил британский инженер Хьюберт Сесил Бут. Ранние модели были настолько громоздкими, что их возили по улицам на конной повозке, а шланг заводили прямо в окна домов.","fact":"Свою идею Бут проверил прямо в лондонском ресторане, приложив ко креслу трубку с платком и убедившись, что пыль остаётся на ткани.","wiki_en":"Vacuum cleaner"},{"name":"Кондиционер","emoji":"❄️","meta":["1902 год","Уиллис Кэрриер","климатическая техника"],"description":"Первую систему для регулирования температуры и влажности воздуха создал американский инженер Уиллис Кэрриер для нужд типографии, где влажность портила печать. Позже кондиционирование распространилось на дома, офисы и автомобили по всему миру.","fact":"Компания, основанная Кэрриером, до сих пор остаётся одним из крупнейших производителей климатической техники.","wiki_en":"Air conditioning"},{"name":"Швейная машина","emoji":"🧵","meta":["XIX век","несколько изобретателей","производство одежды"],"description":"Механизм для автоматизации шитья разрабатывали несколько изобретателей, а патент на машину с челночным стежком получил американец Элиас Хау, чью идею затем довёл до коммерческого успеха Айзек Зингер. Швейная машина резко ускорила производство одежды.","fact":"Между Хау и Зингером долгое время шли судебные тяжбы за права на изобретение швейной машины.","wiki_en":"Sewing machine"},{"name":"Лифт","emoji":"🛗","meta":["1852 год","Элиша Отис","строительство"],"description":"Безопасный пассажирский подъёмник с механизмом, предотвращающим падение кабины при обрыве троса, изобрёл американец Элиша Отис. Именно эта система безопасности сделала возможным строительство высоких зданий и небоскрёбов.","fact":"Отис публично демонстрировал безопасность своего лифта, приказывая обрубать трос кабины прямо во время показа.","wiki_en":"Elevator"},{"name":"Эскалатор","emoji":"↕️","meta":["конец XIX века","несколько изобретателей","перемещение людей"],"description":"Движущуюся наклонную лестницу для подъёма людей независимо предлагали несколько изобретателей в США, а коммерческое название «эскалатор» запатентовала компания Otis Elevator. Устройство стало неотъемлемой частью магазинов, вокзалов и метро.","fact":"Слово «эскалатор» изначально было зарегистрированной торговой маркой и лишь позже стало нарицательным.","wiki_en":"Escalator"},{"name":"Застёжка-молния","emoji":"🤐","meta":["1893–1913 годы","Джадсон и Сундбек","одежда"],"description":"Первые варианты застёжки на основе сцепляющихся зубцов предложил американец Уиткомб Джадсон, а удобную современную конструкцию довёл до совершенства шведско-американский инженер Гидеон Сундбек. Молния постепенно заменила пуговицы и шнуровку на одежде и обуви.","fact":"Первые молнии массово применяли не в одежде, а на обуви и кисетах для табака.","wiki_en":"Zipper"},{"name":"Застёжка-липучка","emoji":"🪢","meta":["1941 год","Жорж де Местраль","материалы"],"description":"Идею застёжки из двух текстильных лент с крючками и петлями швейцарский инженер Жорж де Местраль подсмотрел у природы, разглядывая под микроскопом репейник, прицепившийся к его одежде и шерсти собаки. Так появилась застёжка-липучка, известная под маркой Velcro.","fact":"Название Velcro составлено из французских слов «бархат» и «крючок».","wiki_en":"Hook-and-loop fastener"},{"name":"Джинсы","emoji":"👖","meta":["1873 год","Страусс и Дэвис","одежда"],"description":"Прочные рабочие штаны из плотной хлопковой ткани с металлическими заклёпками на карманах запатентовали американский торговец Ливай Страусс и портной Джейкоб Дэвис. Изначально одежда для золотоискателей и рабочих, джинсы со временем стали одним из символов массовой моды XX века.","fact":"Знаменитая заклёпка на задних карманах изначально ставилась, чтобы карманы не рвались под тяжестью инструментов старателей.","wiki_en":"Jeans"},{"name":"Шариковая ручка","emoji":"🖊️","meta":["1938 год","Ласло Биро","письмо"],"description":"Ручку с вращающимся шариком на конце, который равномерно подавал быстросохнущие чернила, запатентовал венгерский журналист Ласло Биро. Его фамилия до сих пор используется как нарицательное название шариковой ручки во многих странах.","fact":"В английском языке шариковую ручку до сих пор часто называют просто «biro» — в честь её изобретателя.","wiki_en":"Ballpoint pen"},{"name":"Карандаш","emoji":"✏️","meta":["XVI век","Англия","письмо и рисование"],"description":"Современный карандаш с графитовым стержнем появился в Англии после того, как в Камберленде обнаружили крупное месторождение чистого графита. Позже французский инженер Николя-Жак Конте разработал способ смешивать графит с глиной, что позволило регулировать твёрдость грифеля.","fact":"Долгое время графит ошибочно принимали за разновидность свинца, отсюда и происходит английское название карандашного грифеля.","wiki_en":"Pencil"},{"name":"Клейкая лента","emoji":"🎗️","meta":["1930 год","Ричард Дрю","материалы и упаковка"],"description":"Прозрачную клейкую ленту на целлофановой основе изобрёл американский инженер компании 3M Ричард Дрю. Его более раннюю малярную ленту тоже придумал он же, а прозрачный скотч быстро стал незаменимым в быту и офисе.","fact":"Название «скотч» лента получила из-за легенды о том, что первые образцы клея наносили слишком экономно, «по-шотландски».","wiki_en":"Adhesive tape"},{"name":"Пластмасса","emoji":"🧴","meta":["1907 год","Лео Бакеланд","материалы"],"description":"Первый полностью синтетический пластик — бакелит, не встречающийся в природе, — создал американский химик бельгийского происхождения Лео Бакеланд. Изобретение открыло эпоху массового производства пластмассовых изделий на все случаи жизни.","fact":"Из бакелита делали самые разные вещи — от корпусов телефонов и радиоприёмников до дверных ручек и кухонной утвари.","wiki_en":"Bakelite"},{"name":"Бетон","emoji":"🧱","meta":["Древний Рим","римские инженеры","строительство"],"description":"Строительный материал на основе вяжущего вещества и заполнителя активно применяли ещё древнеримские инженеры, добавляя в раствор вулканический пепел для прочности. Современный портландцемент, лежащий в основе бетона сегодня, запатентовал в XIX веке британец Джозеф Аспдин.","fact":"Купол римского Пантеона, построенный из бетона почти два тысячелетия назад, до сих пор остаётся крупнейшим в мире неармированным бетонным куполом.","wiki_en":"Concrete"},{"name":"Стекло","emoji":"🪟","meta":["около 3500 года до н. э.","Месопотамия и Египет","материалы"],"description":"Изготовление стекла из расплавленного песка с добавками освоили ремесленники древней Месопотамии и Египта. Позже техника выдувания, изобретённая на Ближнем Востоке, позволила делать тонкие сосуды и, в конечном счёте, оконные стёкла.","fact":"Древнейшие стеклянные изделия использовали не для окон и посуды, а как имитацию драгоценных камней в украшениях.","wiki_en":"Glass"},{"name":"Зеркало","emoji":"🪞","meta":["Древность, усовершенствовано в XVI веке","Венеция","быт"],"description":"Первые полированные зеркала из металла и обсидиана применяли ещё в древности, а качественные стеклянные зеркала с амальгамой из олова и ртути впервые массово стали делать венецианские мастера на острове Мурано. Их технология долгие века держалась в строжайшем секрете.","fact":"Венеция так оберегала секрет производства зеркал, что мастерам, покинувшим остров, грозило суровое наказание.","wiki_en":"Mirror"},{"name":"Мыло","emoji":"🧼","meta":["Древность","Месопотамия","гигиена"],"description":"Простейшие моющие смеси из жиров и золы использовали ещё в древней Месопотамии и Вавилоне, о чём свидетельствуют сохранившиеся глиняные таблички с рецептами. Твёрдое мыло в привычном виде распространилось гораздо позже, через арабский мир в средневековую Европу.","fact":"Древнейший из известных рецептов мыла записан на вавилонской глиняной табличке возрастом около четырёх тысяч лет.","wiki_en":"Soap"},{"name":"Зубная щётка","emoji":"🪥","meta":["XV век","Китай","гигиена"],"description":"Щётку с щетиной для чистки зубов, закреплённой на костяной или бамбуковой ручке, впервые начали делать в Китае, используя жёсткую щетину со спины кабана. В Европе похожие щётки распространились столетия спустя, а массовое производство наладили только в XIX–XX веках.","fact":"Синтетическую нейлоновую щетину стали ставить на щётки лишь в конце 1930-х годов, а до этого её брали у животных.","wiki_en":"Toothbrush"},{"name":"Унитаз","emoji":"🚽","meta":["XVI–XIX века","Харингтон и Крэппер","сантехника"],"description":"Один из первых смывных туалетов сконструировал придворный поэт Джон Харингтон ещё в XVI веке, но широкого распространения устройство не получило. Современный унитаз с водяным затвором усовершенствовали и распространили инженеры XIX века, включая Томаса Крэппера, чьё имя часто ошибочно называют изобретателем унитаза.","fact":"Вопреки популярной легенде, фамилия Крэппера не является источником английского сленгового слова для обозначения туалета.","wiki_en":"Flush toilet"},{"name":"Консервы","emoji":"🥫","meta":["1810 год","Аппер и Дюран","хранение продуктов"],"description":"Способ длительного хранения еды в герметично закрытых банках после нагревания придумал французский повар Николя Аппер по заказу армии Наполеона. Вскоре британец Питер Дюран запатентовал вариант с металлической консервной банкой вместо стекла.","fact":"Консервный нож изобрели только спустя несколько десятилетий после самих консервов — сначала банки вскрывали молотком и зубилом.","wiki_en":"Canning"},{"name":"Пастеризация","emoji":"🥛","meta":["1864 год","Луи Пастер","пищевая промышленность"],"description":"Метод нагревания жидких продуктов для уничтожения вредных микроорганизмов без потери вкуса разработал французский учёный Луи Пастер, изучавший причины скисания вина и пива. Позже технологию стали широко применять для молока, сделав его безопаснее для хранения и питья.","fact":"Пастер разрабатывал свой метод в первую очередь для спасения французской винодельческой промышленности, а не для молока.","wiki_en":"Pasteurization"},{"name":"Вакцина","emoji":"💉","meta":["1796 год","Эдвард Дженнер","медицина"],"description":"Первую научно обоснованную прививку против оспы создал британский врач Эдвард Дженнер, заметивший, что доярки, переболевшие коровьей оспой, не заражаются человеческой. Его метод положил начало всей современной вакцинации, спасшей миллионы жизней.","fact":"Само слово «вакцина» происходит от латинского названия коровы, поскольку первый материал для прививки брали именно от неё.","wiki_en":"Vaccine"},{"name":"Пенициллин","emoji":"🦠","meta":["1928 год","Александр Флеминг","медицина"],"description":"Первый из широко применяемых антибиотиков случайно обнаружил британский бактериолог Александр Флеминг, заметив, что плесень на забытой чашке с бактериями подавляет их рост. Пригодным для массового производства лекарство сделали позже другие учёные, что позволило спасти множество жизней во время Второй мировой войны и после неё.","fact":"Флеминг чуть не выбросил заплесневевшую чашку Петри, прежде чем обратил внимание на необычный эффект вокруг плесени.","wiki_en":"Penicillin"},{"name":"Анестезия","emoji":"💊","meta":["1846 год","Уильям Мортон","медицина"],"description":"Первую публичную демонстрацию общего наркоза с использованием эфира провёл американский стоматолог Уильям Мортон в бостонской больнице. Это событие открыло эпоху безболезненной хирургии, до этого сопровождавшейся мучительными операциями без обезболивания.","fact":"До открытия анестезии хирурги ценились не только за мастерство, но и за скорость операций, ведь пациент терпел боль в сознании.","wiki_en":"General anaesthesia"},{"name":"Рентгеновский аппарат","emoji":"🩻","meta":["1895 год","Вильгельм Рентген","медицина"],"description":"Излучение, способное просвечивать плотные ткани и показывать кости под кожей, случайно открыл немецкий физик Вильгельм Рентген во время экспериментов с электронно-лучевой трубкой. За это открытие он получил первую в истории Нобелевскую премию по физике.","fact":"Первый рентгеновский снимок в истории Рентген сделал с кисти руки собственной жены.","wiki_en":"X-ray"},{"name":"МРТ","emoji":"🧲","meta":["1970-е годы","Лотербур и Мэнсфилд","медицина"],"description":"Метод получения изображений внутренних органов с помощью магнитного поля без вредного излучения разработали американский химик Пол Лотербур и британский физик Питер Мэнсфилд. Магнитно-резонансная томография стала одним из важнейших инструментов диагностики в современной медицине.","fact":"За разработку метода МРТ его создатели получили Нобелевскую премию по физиологии и медицине уже в XXI веке.","wiki_en":"Magnetic resonance imaging"},{"name":"Кардиостимулятор","emoji":"❤️","meta":["1958 год","Эльмквист и Сеннинг","медицина"],"description":"Первый имплантируемый электрокардиостимулятор, вживлённый непосредственно пациенту, разработали и установили шведский инженер Руне Эльмквист и хирург Оке Сеннинг. Устройство помогает сердцу поддерживать правильный ритм, спасая жизни людей с нарушениями проводимости.","fact":"Первый пациент с имплантированным кардиостимулятором прожил после операции ещё несколько десятилетий, пережив множество замен устройства.","wiki_en":"Artificial cardiac pacemaker"},{"name":"Инсулин","emoji":"🧪","meta":["1921 год","Бантинг и Бест","медицина"],"description":"Гормон для лечения сахарного диабета выделили канадские учёные Фредерик Бантинг и Чарльз Бест в лаборатории Торонтского университета. До этого открытия диагноз «диабет первого типа» практически неизбежно означал скорую смерть.","fact":"Права на патент инсулина его создатели продали университету символически, всего за один доллар, чтобы лекарство осталось доступным.","wiki_en":"Insulin"},{"name":"Контактные линзы","emoji":"👁️","meta":["1887–1888 годы","несколько изобретателей","медицина"],"description":"Первые стеклянные линзы, накладываемые прямо на глаз для коррекции зрения, независимо предложили несколько европейских специалистов, включая немецкого стекольщика Ф. А. Мюллера. Удобные мягкие линзы из полимеров появились гораздо позже, в середине XX века, благодаря чешскому химику Отто Вихтерле.","fact":"Первый прототип мягкой контактной линзы Отто Вихтерле собрал дома с помощью самодельного устройства, похожего на проигрыватель для пластинок.","wiki_en":"Contact lens"},{"name":"Банковская карта","emoji":"💳","meta":["1950 год","Diners Club","финансы"],"description":"Первую массовую платёжную карту для расчётов в ресторанах выпустила американская компания Diners Club. Она заменяла наличные для постоянных клиентов, а вскоре подобные карты стали выпускать и банки, положив начало современной безналичной оплате.","fact":"Первая карта Diners Club была сделана из плотного картона, а не пластика.","wiki_en":"Diners Club International"},{"name":"Банкомат","emoji":"🏧","meta":["1967 год","Джон Шеппард-Баррон","финансы"],"description":"Первый банкомат для выдачи наличных без участия кассира установил в Лондоне изобретатель Джон Шеппард-Баррон, придумавший идею во время принятия ванны. Устройство избавило людей от необходимости подстраиваться под часы работы отделений банка.","fact":"На месте, где в лондонском Энфилде заработал первый банкомат, теперь висит памятная табличка в честь этого события.","wiki_en":"Automated teller machine"},{"name":"Штрихкод","emoji":"🏷️","meta":["1952 год","Вудленд и Сильвер","торговля"],"description":"Идею кодирования информации о товаре в виде чередующихся полос предложили американцы Норман Вудленд и Бернард Сильвер, вдохновившись азбукой Морзе, которую рисовали пальцами на песке. Массовое применение штрихкоды получили только спустя два десятилетия с развитием сканеров.","fact":"Первым товаром, отсканированным штрихкодом на настоящей кассе супермаркета, стала пачка жевательной резинки.","wiki_en":"Barcode"},{"name":"Биткойн","emoji":"🪙","meta":["2008–2009 годы","Сатоши Накамото","финансы"],"description":"Первую децентрализованную криптовалюту описал в своей статье и запустил в виде программы аноним или группа людей под псевдонимом Сатоши Накамото. Настоящая личность создателя биткойна до сих пор остаётся неизвестной.","fact":"Первый блок в цепочке биткойна содержал зашифрованную ссылку на газетный заголовок о спасении банков во время финансового кризиса.","wiki_en":"Bitcoin"},{"name":"Нейросеть","emoji":"🧠","meta":["середина XX века","Маккалок и Питтс","искусственный интеллект"],"description":"Математическую модель, имитирующую работу нейронов мозга, впервые предложили учёные Уоррен Маккалок и Уолтер Питтс. Их идеи легли в основу перцептрона Фрэнка Розенблатта, а десятилетия спустя — современных глубоких нейросетей, лежащих в основе искусственного интеллекта.","fact":"Первые модели искусственных нейронов появились ещё в 1940-е годы, задолго до того, как компьютеры стали достаточно мощными для их обучения.","wiki_en":"Artificial neural network"},{"name":"Робот","emoji":"🤖","meta":["XX век","несколько изобретателей","автоматизация"],"description":"Первые программируемые промышленные манипуляторы для автоматизации работы на заводах создали инженеры середины XX века, включая американца Джорджа Девола с его роботом Unimate. Само слово «робот» гораздо раньше прозвучало в пьесе чешского писателя Карела Чапека, которому его подсказал брат Йозеф.","fact":"Слово «робот» происходит от чешского слова, обозначающего тяжёлый подневольный труд.","wiki_en":"Robot"},{"name":"Конвейер","emoji":"🏭","meta":["1913 год","Генри Форд","производство"],"description":"Движущуюся сборочную линию для массового производства автомобилей внедрил американский промышленник Генри Форд на своём заводе. Это резко ускорило выпуск машин и снизило их стоимость, сделав автомобиль доступным для обычных людей.","fact":"Благодаря конвейеру Форда время сборки одного автомобиля сократилось с более чем двенадцати часов до примерно полутора.","wiki_en":"Assembly line"},{"name":"Светофор","emoji":"🚦","meta":["1868 год","Джон Пик Найт","дорожное движение"],"description":"Первое устройство для регулирования уличного движения с помощью цветных сигналов установили возле британского парламента по проекту инженера Джона Пика Найта. Оно работало на газовых фонарях и вскоре взорвалось, после чего идею на время забросили, вернувшись к ней уже в эпоху автомобилей.","fact":"Первый светофор в Лондоне взорвался всего через несколько недель после установки из-за утечки газа.","wiki_en":"Traffic light"},{"name":"Шахматы","emoji":"♟️","meta":["около VI века","Индия","настольные игры"],"description":"Игра, ставшая прообразом современных шахмат, зародилась в древней Индии под названием чатуранга и изображала расстановку войск на поле боя. Через Персию и арабский мир игра распространилась в Европу, где постепенно приобрела привычные правила и фигуры.","fact":"Название игры «шахматы» происходит от персидской фразы «шах мат», означающей «король повержен».","wiki_en":"Chess"},{"name":"Кубик Рубика","emoji":"🧩","meta":["1974 год","Эрнё Рубик","головоломки"],"description":"Механическую головоломку из разноцветных вращающихся граней придумал венгерский архитектор и преподаватель Эрнё Рубик, пытаясь объяснить студентам принципы пространственного движения. Игрушка стала одним из самых продаваемых товаров в истории и породила отдельный вид спортивных соревнований — спидкубинг.","fact":"По собственному признанию Рубика, ему самому потребовался почти месяц, чтобы впервые полностью собрать изобретённый им кубик.","wiki_en":"Rubik's Cube"}];
